import type { TimeDetails } from '../../../core/types/time.js';
/** An object containing all properties of the datepicker value. */
export interface DatePickerValue {
    /** ISO string date value (null when the user input is invalid). */
    value: string | null;
    /** Date-time value parsed as TimeDetails (null when the user input is invalid). */
    details: TimeDetails | null;
    /** ISO string date value formatted for display. */
    displayValue: string;
}
